The commission math is pure logic embedded in `CalcResult` but impossible to test because it's not extracted. The formulas have real financial impact.

**Missing tests:**
- List vs floor pricing selection
- Base commission at various rates
- Velocity bonus calculation (`storeCount × $75`)
- Zero-units edge case (division guard on `margin`)
- Margin health thresholds (60% = Healthy, 45% = Fair, <45% = Tight)

```ts
// tests/calcLogic.test.ts
import { describe, it, expect } from 'vitest'

const LIST_PRICE = 32.5
const FLOOR_PRICE = 30
const VELOCITY_BONUS = 75

function calcResult(units: number, tier: 'list' | 'floor', rate: number, hasBonus: boolean, storeCount: number) {
  const price = tier === 'list' ? LIST_PRICE : FLOOR_PRICE
  const gross = units * price
  const baseComm = gross * (rate / 100)
  const bonusTotal = hasBonus ? storeCount * VELOCITY_BONUS : 0
  const totalComm = baseComm + bonusTotal
  const net = gross - totalComm
  const margin = gross > 0 ? (net / gross) * 100 : 0
  return { gross, baseComm, bonusTotal, totalComm, net, margin }
}

describe('calcResult', () => {
  it('uses list price of $32.50', () => {
    expect(calcResult(100, 'list', 10, false, 0).gross).toBe(3250)
  })

  it('uses floor price of $30.00', () => {
    expect(calcResult(100, 'floor', 10, false, 0).gross).toBe(3000)
  })

  it('calculates base commission correctly', () => {
    const { baseComm } = calcResult(120, 'list', 10, false, 0)
    expect(baseComm).toBe(390) // 120 * 32.5 * 0.10
  })

  it('adds velocity bonus per store', () => {
    const { bonusTotal } = calcResult(120, 'list', 10, true, 3)
    expect(bonusTotal).toBe(225) // 3 * $75
  })

  it('applies no bonus when hasBonus is false', () => {
    expect(calcResult(120, 'list', 10, false, 5).bonusTotal).toBe(0)
  })

  it('returns 0% margin when units is 0', () => {
    expect(calcResult(0, 'list', 10, false, 0).margin).toBe(0)
  })

  it('margin health: ≥60% is Healthy', () => {
    const { margin } = calcResult(120, 'list', 5, false, 0)
    expect(margin).toBeGreaterThanOrEqual(60)
  })

  it('margin health: <45% is Tight at high commission rate', () => {
    const { margin } = calcResult(120, 'list', 25, false, 0)
    expect(margin).toBeLessThan(45)
  })
})
```

