`daysUntil` appears verbatim in both `Dashboard.tsx:20` and `Inventory.tsx:12`. No tests, and incorrect inputs (empty string, past date) are unchecked.

```ts
// tests/daysUntil.test.ts
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'

function daysUntil(dateStr: string) {
  const diff = new Date(dateStr).getTime() - Date.now()
  return Math.ceil(diff / 86400000)
}

describe('daysUntil', () => {
  beforeEach(() => { vi.useFakeTimers() })
  afterEach(() => { vi.useRealTimers() })

  it('returns positive days for a future date', () => {
    vi.setSystemTime(new Date('2026-01-01'))
    expect(daysUntil('2026-01-31')).toBe(30)
  })

  it('returns 0 for today', () => {
    vi.setSystemTime(new Date('2026-06-22'))
    expect(daysUntil('2026-06-22')).toBe(0)
  })

  it('returns negative days for a past date', () => {
    vi.setSystemTime(new Date('2026-06-22'))
    expect(daysUntil('2026-01-01')).toBeLessThan(0)
  })

  // Edge case: no guard against invalid date strings
  it('returns NaN for an invalid date string', () => {
    expect(daysUntil('')).toBeNaN()
  })
})
```

**Recommendation:** Extract to `src/lib/utils.ts` and import from both files.

