Embedded in `Inventory.tsx:16-33`. Division guards exist but `days=0` and `delivered=0` paths produce `0` silently.

```ts
// tests/sellThrough.test.ts
import { describe, it, expect } from 'vitest'

function calcSellThrough(delivered: number, sold: number, days: number) {
  const pct = delivered > 0 ? Math.min(100, (sold / delivered) * 100) : 0
  const pace = days > 0 ? (sold / days) * 90 : 0
  const color = pct >= 80 ? '#22c55e' : pct >= 40 ? '#eab308' : '#ef4444'
  return { pct, pace, color }
}

describe('SellThroughBar calculations', () => {
  it('returns 0% when nothing delivered', () => {
    expect(calcSellThrough(0, 0, 10).pct).toBe(0)
  })

  it('caps pct at 100 when sold > delivered', () => {
    expect(calcSellThrough(60, 80, 30).pct).toBe(100)
  })

  it('returns 0 pace when days is 0', () => {
    expect(calcSellThrough(60, 30, 0).pace).toBe(0)
  })

  it('color is green at ≥80%', () => {
    expect(calcSellThrough(60, 50, 30).color).toBe('#22c55e')
  })

  it('color is yellow at 40–79%', () => {
    expect(calcSellThrough(60, 30, 30).color).toBe('#eab308') // 50%
  })

  it('color is red below 40%', () => {
    expect(calcSellThrough(60, 10, 30).color).toBe('#ef4444') // ~16%
  })
})
