`useAuth.tsx` has no tests. The `isAdmin` check is a hardcoded email comparison that's security-relevant.

```tsx
// tests/useAuth.test.tsx
import { renderHook } from '@testing-library/react'
import { describe, it, expect, vi } from 'vitest'

// Mock supabase
vi.mock('../src/lib/supabase', () => ({
  supabase: {
    auth: {
      getSession: vi.fn().mockResolvedValue({ data: { session: null } }),
      onAuthStateChange: vi.fn().mockReturnValue({ data: { subscription: { unsubscribe: vi.fn() } } }),
      signInWithPassword: vi.fn(),
      signOut: vi.fn(),
    },
  },
}))

import { AuthProvider, useAuth } from '../src/hooks/useAuth'
import { supabase } from '../src/lib/supabase'

const wrapper = ({ children }: { children: React.ReactNode }) => (
  <AuthProvider>{children}</AuthProvider>
)

describe('useAuth', () => {
  it('starts in loading state', () => {
    const { result } = renderHook(() => useAuth(), { wrapper })
    expect(result.current.loading).toBe(true)
  })

  it('isAdmin is false when no user', async () => {
    const { result } = renderHook(() => useAuth(), { wrapper })
    expect(result.current.isAdmin).toBe(false)
  })

  it('isAdmin is true only for ryan@liftedextracts.co', async () => {
    // Simulate admin user session
    vi.mocked(supabase.auth.getSession).mockResolvedValueOnce({
      data: { session: { user: { email: 'ryan@liftedextracts.co' } } as any }
    })
    const { result, rerender } = renderHook(() => useAuth(), { wrapper })
    await vi.waitFor(() => expect(result.current.loading).toBe(false))
    expect(result.current.isAdmin).toBe(true)
  })

  it('isAdmin is false for other emails', async () => {
    vi.mocked(supabase.auth.getSession).mockResolvedValueOnce({
      data: { session: { user: { email: 'other@example.com' } } as any }
    })
    const { result } = renderHook(() => useAuth(), { wrapper })
    await vi.waitFor(() => expect(result.current.loading).toBe(false))
    expect(result.current.isAdmin).toBe(false)
  })

  it('signIn calls supabase with credentials', async () => {
    vi.mocked(supabase.auth.signInWithPassword).mockResolvedValueOnce({ error: null } as any)
    const { result } = renderHook(() => useAuth(), { wrapper })
    await result.current.signIn('test@example.com', 'password123')
    expect(supabase.auth.signInWithPassword).toHaveBeenCalledWith({
      email: 'test@example.com',
      password: 'password123',
    })
  })

  it('signIn returns error on failure', async () => {
    const mockError = new Error('Invalid credentials')
    vi.mocked(supabase.auth.signInWithPassword).mockResolvedValueOnce({ error: mockError } as any)
    const { result } = renderHook(() => useAuth(), { wrapper })
    const { error } = await result.current.signIn('bad@example.com', 'wrong')
    expect(error).toBe(mockError)
  })
})
