`submitOrder` at `Inventory.tsx:73` enforces a 60-unit minimum (`MIN_ORDER`) but there are no tests for it, and the Supabase error path only sets an error string without clearing it on retry.

```tsx
// tests/Inventory.test.tsx
import { render, screen, fireEvent, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, it, expect, vi } from 'vitest'

vi.mock('../src/lib/supabase', () => ({
  supabase: {
    from: vi.fn(() => ({
      select: vi.fn().mockReturnThis(),
      order: vi.fn().mockReturnThis(),
      limit: vi.fn().mockResolvedValue({ data: [] }),
      insert: vi.fn().mockResolvedValue({ error: null }),
    })),
  },
}))

import { Inventory } from '../src/pages/Inventory'

describe('Inventory — order validation', () => {
  it('shows error when units < 60', async () => {
    render(<Inventory />)
    await userEvent.click(screen.getByText('New order'))
    const unitsInput = screen.getByLabelText(/units/i)
    await userEvent.clear(unitsInput)
    await userEvent.type(unitsInput, '30')
    await userEvent.click(screen.getByText('Create order'))
    expect(screen.getByText(/minimum order is 60 units/i)).toBeInTheDocument()
  })

  it('does not submit when units < 60', async () => {
    const { supabase } = await import('../src/lib/supabase')
    render(<Inventory />)
    await userEvent.click(screen.getByText('New order'))
    const unitsInput = screen.getByLabelText(/units/i)
    await userEvent.clear(unitsInput)
    await userEvent.type(unitsInput, '1')
    await userEvent.click(screen.getByText('Create order'))
    expect(supabase.from('orders').insert).not.toHaveBeenCalled()
  })

  it('closes modal on successful order', async () => {
    render(<Inventory />)
    await userEvent.click(screen.getByText('New order'))
    // Select a store, set valid units, submit
    // ... (requires stores data in mock)
    await waitFor(() => {
      expect(screen.queryByText('New Order')).not.toBeInTheDocument()
    })
  })
})
