`Dashboard.tsx:73-97` has complex aggregation: filtering active accounts, summing units, flagging reorder and overdue stores, and computing rep bonuses. All untested.

```ts
// tests/dashboardLogic.test.ts
import { describe, it, expect, vi } from 'vitest'

// Extracted logic (currently embedded in useEffect — worth extracting)
function computeStats(stores: any[], orders: any[]) {
  const today = new Date()
  const thirtyDaysAgo = new Date(today.getTime() - 30 * 86400000).toISOString()

  const activeAccounts = stores.filter(s => s.status === 'active').length
  const unitsSoldThisMonth = orders.reduce((sum: number, o: any) => sum + (o.units || 0), 0)
  const grossRevenue = orders.reduce((sum: number, o: any) => sum + o.units * o.price_per_unit, 0)
  const netMarginThisMonth = grossRevenue * 0.62

  const storesNeedingReorder = stores.filter(s => {
    if (!s.next_reorder_date) return false
    return new Date(s.next_reorder_date) <= new Date(today.getTime() + 7 * 86400000)
  }).length

  const storesOverdueVisit = stores.filter(s => {
    if (!s.last_order_date) return true
    return s.last_order_date < thirtyDaysAgo
  }).length

  return { activeAccounts, unitsSoldThisMonth, netMarginThisMonth, storesNeedingReorder, storesOverdueVisit }
}

describe('Dashboard aggregation', () => {
  it('counts only active stores', () => {
    const stores = [
      { status: 'active' }, { status: 'active' }, { status: 'prospect' }
    ]
    expect(computeStats(stores, []).activeAccounts).toBe(2)
  })

  it('sums units across all orders', () => {
    const orders = [{ units: 60, price_per_unit: 32.5 }, { units: 120, price_per_unit: 30 }]
    expect(computeStats([], orders).unitsSoldThisMonth).toBe(180)
  })

  it('applies 62% net margin estimate', () => {
    const orders = [{ units: 100, price_per_unit: 32.5 }]
    const { netMarginThisMonth } = computeStats([], orders)
    expect(netMarginThisMonth).toBeCloseTo(3250 * 0.62)
  })

  it('flags store needing reorder within 7 days', () => {
    vi.useFakeTimers()
    vi.setSystemTime(new Date('2026-06-22'))
    const stores = [{ next_reorder_date: '2026-06-27', last_order_date: '2026-06-01' }]
    expect(computeStats(stores, []).storesNeedingReorder).toBe(1)
    vi.useRealTimers()
  })

  it('flags store with no last_order_date as overdue', () => {
    const stores = [{ next_reorder_date: null, last_order_date: null }]
    expect(computeStats(stores, []).storesOverdueVisit).toBe(1)
  })

  it('rep bonus: $75 per 60-unit block', () => {
    const bonus = Math.floor(180 / 60) * 75
    expect(bonus).toBe(225) // 3 blocks * $75
  })

  it('rep bonus: 0 when under 60 units', () => {
    expect(Math.floor(59 / 60) * 75).toBe(0)
  })
})
